*TO BE RUN IN THE LOCAL COMPUTER AND UPLOADED TO WRDS HOME DIRECTORY;
****** Prepare file with permnos and gvkeys FOR ANNUAL DATA ****************;
* File AT.Compdata_perm was downloaded from WRDS. It contains raw Compustat variables;

data AT.PERMNOGVKEY2017 (keep=gvkey FYEAR permno datadate bgdt);
set AT.Compdata_perm (keep=GVKEY DATADATE FYEAR PERMNO INDFMT obs=900000 where=(indfmt="INDL"));

* IF YOU RUN THE FOLLOWING CODE IN WRDS, THE UNIX COMMAND IS:  nohup get_bas_dvolat_2017.sas &  ;
************************************************************************************************;
%let wrds = wrds.wharton.upenn.edu 4016;options comamid=TCP;signon wrds username=_prompt_;

RSUBMIT;
options errors=1 noovp;
options nocenter ps=max ls=78;
options mprint source nodate symbolgen macrogen;
options msglevel=i;

libname mydata '[redacted-path-e1f3f7c8b9f7]';
*Upload to home directory the table with the link PERMNO-GVKEY ;
proc upload data=AT.PERMNOGVKEY2017 out=mydata.PERMNOGVKEY2017;
data mydata.permnos;
set mydata.PERMNOGVKEY2017;
if FYEAR>1961;
proc sql;
  create table bas_dvolat as
  select co.*, std(ret) as dvolat, n(ret) as n_dvolat, 
               mean(abs(abs(askhi)-abs(bidlo))/( (abs(askhi)+abs(bidlo))/2 )) as bas, n(askhi) as n_bas
  from mydata.permnos as co, crsp.dsf (keep=permno date ret askhi bidlo where=(askhi ne 0 & bidlo ne 0))  as cr 
  where cr.permno=co.permno
  and co.bgdt <= cr.date <= co.datadate
  group by  co.permno, co.datadate;
quit;
proc sort data=bas_dvolat nodupkey out=mydata.rawbasdvolat2017;
by gvkey fyear;

proc download data=mydata.rawbasdvolat2017 out=AT.rawbasdvolat2017;
run;

ENDRSUBMIT;

*This step pulls data from compustat and constructs initial variables;
* File AT.Compdata_perm was downloaded from WRDS. It contains raw Compustat variables;
data comp0 (keep=gvkey permno FYEAR datadate retbgdt0 FPS LNASSETS SALESGR SIC CSHO_lag) ;
set AT.compdata_perm (where=(INDFMT="INDL" and (1987 le FYEAR) and PRCC_F>0 and CSHO>0 and AT>0) obs=900000); 

* Drop financial firms and regulated industries;
if sic>5999 & sic<7000 or sic>=4900 & sic<=4949 then delete ; 

FPS=(2833<=SIC<=2836 or 8731<=SIC<=8734 or 7371<=SIC<=7379 or 3570<=SIC<=3577 or 3600<=SIC<=3674);
LNASSETS=log(AT);
if gvkey=lag(gvkey) and (fyear-1)=lag(fyear) then m1=1; else m1 = .;
SALE_lag=lag(SALE)*m1;
if SALE_lag>0 then SALESGR=(SALE-SALE_lag)/SALE_lag;
CSHO_lag=lag(CSHO)*m1;

*This step sets up the beginning and ending dates for monthly return windows;
format retbgdt0 date9.;
retbgdt0=intnx('month',DATADATE,-11); 

* COMPUTE RETURNS VARIABLES;
* FILE GLOPREM.CRSP2019 WAS DOWNLOADED FROM WRDS AND IT CONTAINS CRSP MONTHLY RETURNS;
proc sql;
  create table  ret_vars as
  select co.*, exp(sum(log(1+ret)))-1 as RET, n(ret) as n_periods, std(ret) as RET_STDEV, sum(vol)/10000 as turnovr
  from comp0 as co, GLOPREM.CRSP2019 as cr 
  where cr.permno=co.permno
  and co.retbgdt0 <= cr.date <= co.datadate
  group by  co.permno, co.datadate;
quit;

* GET DATA FOR DUTTA, PATATOUKAS & WANG (2020) VARIABLES;
* FILE AT.Funda1950_2017 CONTAINS ADDITIONAL RAW COMPUSTAT VARIABLES DOWNLOADED FROM WRDS;

data DPW (keep=gvkey fyear DPC RECCH INVCH APALCH TXACH AOLOCH TXDC ESUBC SPPIV IVNCF CCACC DA STACC OTH CFI OPACC CCACC_lag CCACCmve CCACCmve_lag INVT INVT_lag) ;
set AT.Funda1950_2017 (keep=gvkey fyear DPC RECCH INVCH APALCH TXACH AOLOCH TXDC ESUBC SPPIV IVNCF AT SPI XIDO PRCC_F CSHO INVT where=(AT>0 and 1987 le FYEAR));
if gvkey=lag(gvkey) and (fyear-1)=lag(fyear) then m1=1; else m1 = .;
lagAT=lag(AT)*m1;
INVT_lag=lag(INVT)*m1;
MVE=PRCC_F*CSHO;
MVE_lag=lag(MVE)*m1;
SPI_lag=lag(SPI)*m1;
XIDO_lag=lag(XIDO)*m1;
CCACC=sum(SPI, -XIDO, 0)/lagAT;
if CCACC>0 then CCACC=0;
DA=-sum(DPC, 0)/lagAT;
STACC=sum(-RECCH, -INVCH, -APALCH, -TXACH, -AOLOCH, 0)/lagAT; 
OTH=sum(-TXDC, -ESUBC, -SPPIV, 0)/lagAT;
CFI=sum(IVNCF, 0)/lagAT;
OPACC=SUM(CCACC, STACC, DA, OTH);
CCACC_lag=sum(SPI_lag, -XIDO_lag, 0)/lagAT;
if CCACC_lag>0 then CCACC_lag=0;
if MVE_lag>0 then CCACCmve=sum(SPI, -XIDO, 0)/MVE_lag;
if CCACCmve>0 then CCACCmve=0;
if MVE_lag>0 then CCACCmve_lag=sum(SPI_lag, -XIDO_lag, 0)/MVE_lag;
if CCACCmve_lag>0 then CCACCmve_lag=0;

* MERGE PIN DATA (from DUARTE & YOUNG, 2009 JFE) ;
data data AT.sample2017JAR (drop=pin);
merge AT.sample2017JAR (in=in1) AT.Pins_1983_2004 (keep=gvkey fyear pin);
if in1;
by gvkey fyear;
pin2=pin;
proc means;
var pin2;
run;

*MERGE PPENT INTAN CAPX SPPE AQC ADDITIONAL VARIABLES;
*FILE AT.Funda1950_2017 CONTAINS ADDITIONAL RAW COMPUSTAT VARIABLES DOWNLOADED FROM WRDS;
data ADDLVARS;
set AT.Funda1950_2017 (keep=gvkey fyear PPENT INTAN CAPX SPPE AQC  where=(1988 le FYEAR)  );
proc sort nodupkey;
by gvkey fyear;
run;
data AT.sample2017JAR ;
merge AT.sample2017JAR (in=in1) ADDLVARS;
if in1;
by gvkey fyear;
run;

* MERGE LITIGATION PROXY WITH MAIN SAMPLE;
data AT.sample2017JAR ;
merge AT.sample2017JAR (in=in1) AT.litig (keep=gvkey fyear  plit2_lag );
if in1;
by gvkey fyear;
run;

* EXPORT SAMPLE TO STATA;
PROC EXPORT DATA= AT.sample2017JAR
            OUTFILE= "[redacted-path-d746d7c09bbe]" 
            DBMS=STATA REPLACE;
RUN;

*This step pulls data from compustat and constructs initial variables. Some of them will not be used eventually;
* File AT.Compdata_perm was downloaded from WRDS. It contains raw Compustat variables;
data comp0 (drop=COGS INVT AP INVT_lag1 AP_lag1 m1) ;
set AT.compdata_perm (where=(INDFMT="INDL" and (1987 le FYEAR) and PRCC_F>0 and CSHO>0) obs=900000); 

SIC2=substr(SIC,1,2)*1; 
GICS=substr(GIND,1,2)*1;  
if CAPX='.' then CAPX=0;
if AQC='.' then AQC=0;
if SPPE='.' then SPPE=0;
if XIDOC='.' then XIDOC=0;
if XIDO='.' then XIDO=0;
if FOPO='.' then FOPO=0;
if TXBCO='.' then TXBCO=0;
if STKCO='.' then STKCO=0;
if missing(IDIT)=1 then IDIT=0;
if missing(MII)=1 then MII=0;
if missing(XINT)=1 then XINT=0;
if missing(RECTA)=1 then RECTA=0;
if missing(MSA)=1 then MSA=0;

if gvkey=lag(gvkey) and (fyear-1)=lag(fyear) then m1=1; else m1 = .;
RECT_lag1=lag(RECT)*m1;
INVT_lag1=lag(INVT)*m1;
AP_lag1=lag(AP)*m1;
if (COGS-INVT+INVT_lag1)>0 and SALE>0 and COGS>0 then
  CYCLE=360*((RECT+RECT_lag1)/2)/SALE + 360*((INVT+INVT_lag1)/2)/COGS - 360*((AP+AP_lag1)/2)/(COGS-INVT+INVT_lag1);
CYCLE_lag=lag(CYCLE)*m1;
AJEX_lag1=lag(AJEX)*m1;
LSALE=lag(SALE)*m1;

* COMPUTE ANNUAL RETURNS ENDING AT FYE;
* FILE AT.CRSP1950_2017 WAS DOWLOADED FROM WRDS AND IT CONTAINS RAW RETURNS;
proc sql;
  create table  cum_returns as
  select co.*, exp(sum(log(1+ret)))-1 as RET12, n(ret) as n_periods 
  from comp0 as co, AT.CRSP1950_2017 (keep=permno date ret)  as cr 
  where cr.permno=co.permno
  and co.retbgdt0 <= cr.date <= co.datadate
  group by  co.permno, co.datadate;
quit;
proc sort nodupkey;
by gvkey FYEAR;
run;

data comp0 ;
set cum_returns;
by gvkey FYEAR;
if n_periods=12 ;
run;

* COMPUTE ANNUAL RETURNS ENDING 3 MONTHS AFTER FYE (EVENTUALLY NOT USED);
proc sql;
  create table  cum_returns3 as
  select co.*, exp(sum(log(1+ret)))-1 as RET15, n(ret) as n_periods15 
  from comp0 as co, AT.CRSP1950_2017 (keep=permno date ret)  as cr 
  where cr.permno=co.permno
  and co.retbgdt3 <= cr.date <= co.retenddt3
  group by  co.permno, co.datadate;
quit;
proc sort nodupkey;
by gvkey FYEAR;
run;

data comp0 (drop=retbgdt3 retenddt3 retbgdt0 n_periods n_periods15 ret12 ret15);

* WINSORIZE ADDITIONAL VARIABLES ANNUALLY AT THE 1 AND 99 PERCENTILES;
%winsor(dsetin=AT.sample2017JAR, dsetout=AT.sample2017JAR, vars= CFORES, byvar=fyear, type=winsor, pctl=1 99); 
proc sort nodupkey;  by gvkey fyear; 
run;

* COMPUTE CFORES VARIABLE AS IN DUTTA, PATATOUKAS AND WANG (2020);
proc sql;
   create table compdatacfoa
   as select * 
   from comp1
   where CFOA*CFOA_lag ne .
   group by SIC2,fyear
   having n(gvkey) >= 10
   order by SIC2, FYEAR;
   quit;
proc reg data=compdata noprint outest=par_c;
by SIC2 FYEAR;
model CFOA=CFOA_lag  /rsquare ;
output out=CFORES (keep=gvkey fyear CFORES) r=CFORES ;
proc sort nodupkey data=CFORES;

* UCCACCmve;
proc sql;
   create table compdata
   as select * 
   from comp1
   where CCACCmve*CCACCmve_lag  ne .
   having n(gvkey) >= 10
   order by SIC2, FYEAR;
   quit;
proc reg data=compdata noprint outest=par_mj6;
by SIC2 FYEAR;
model CCACCmve=CCACCmve_lag /rsquare;

* Annual quintile portfolios of beginning-of-year SIZE and beginning-of-year BM;
proc sort data=comp1 ;
by FYEAR SIZE_lag ; run;
proc rank data=comp1 groups=5 out=comp2;
var BM_lag;
ranks QBM_lag ;
by FYEAR QSIZE_lag ;
run;

* Add the first date in CRSP to compute the age of the firm;
* The file "AT.crspbegdates" is obtained from the CRSP Stock Header Information;
data date1 (keep=permno firstdate);
set AT.crspbegdates;
firstdate=begprc;
format firstdate YYMMDDN8.;
run;
proc sql;
  create table  comp00 as
  select co.*, d.firstdate
  from comp0 as co, date1 as d 
  where co.permno=d.permno ;
quit;

